function finish(context is Context, bodies is Query, name is string, rgb is array)
{
    setProperty(context, {"entities" : bodies, "propertyType" : PropertyType.NAME, "value" : name});
    setProperty(context, {"entities" : bodies, "propertyType" : PropertyType.APPEARANCE,
                "value" : color(rgb[0] / 255, rgb[1] / 255, rgb[2] / 255)});
}

function torus(context is Context, id is Id, center is Vector, axis is Vector,
               major is ValueWithUnits, minor is ValueWithUnits) returns Query
{
    var reference = abs(axis[0]) < 0.8 ? vector(1, 0, 0) : vector(0, 1, 0);
    var radial = normalize(cross(axis, reference));
    var sketch = newSketchOnPlane(context, id + "section", {
                "sketchPlane" : plane(center, cross(radial, axis), radial)});
    skCircle(sketch, "circle", {"center" : vector(major, 0 * millimeter), "radius" : minor});
    skSolve(sketch);
    opRevolve(context, id + "revolve", {"entities" : qSketchRegion(id + "section"),
                "axis" : line(center, axis), "angleForward" : 360 * degree});
    opDeleteBodies(context, id + "clean", {"entities" : qCreatedBy(id + "section", EntityType.BODY)});
    return qCreatedBy(id + "revolve", EntityType.BODY);
}

function roundedBody(context is Context, id is Id, halfX is number, halfY is number,
                corner is number, origin is Vector, normal is Vector,
                height is number, unit is ValueWithUnits) returns Query
{
    var sketch = newSketchOnPlane(context, id + "outline", {
                "sketchPlane" : plane(origin * unit, normal, vector(1, 0, 0))});
    var points = [];
    for (var i = 0; i < 4; i += 1)
    {
        var angle = (i * 90) * degree;
        var cx = (i == 0 || i == 3) ? halfX - corner : -halfX + corner;
        var cy = (i < 2) ? halfY - corner : -halfY + corner;
        for (var j = 0; j <= 12; j += 1)
        {
            var a = angle + j * 7.5 * degree;
            points = append(points, vector(cx + corner * cos(a), cy + corner * sin(a)) * unit);
        }
    }
    points = append(points, points[0]);
    skPolyline(sketch, "boundary", {"points" : points});
    skSolve(sketch);
    opExtrude(context, id + "body", {"entities" : qSketchRegion(id + "outline"),
                "direction" : normal, "endBound" : BoundingType.BLIND, "endDepth" : height * unit});
    opDeleteBodies(context, id + "clean", {"entities" : qCreatedBy(id + "outline", EntityType.BODY)});
    return qCreatedBy(id + "body", EntityType.BODY);
}

function pointOnTorus(center is Vector, u is Vector, v is Vector, n is Vector,
                      theta is ValueWithUnits, phi is ValueWithUnits, unit is ValueWithUnits) returns Vector
{
    return center + (43 + 14 * cos(phi)) * unit * (cos(theta) * u + sin(theta) * v)
                  + 14 * sin(phi) * unit * n;
}

function arrow(context is Context, id is Id, node is Vector, surface is Vector,
               unit is ValueWithUnits, name is string, rgb is array) returns Query
{
    var direction = normalize(surface - node);
    var tip = surface + 2.5 * unit * direction;
    var headBase = tip - 14 * unit * direction;
    fCylinder(context, id + "shaft", {
                "bottomCenter" : node + 9.6 * unit * direction,
                "topCenter" : headBase + 1 * unit * direction, "radius" : 1.95 * unit});
    fCone(context, id + "head", {"bottomCenter" : headBase, "topCenter" : tip,
                "bottomRadius" : 5.6 * unit, "topRadius" : 0 * unit});
    var parts = qUnion([qCreatedBy(id + "shaft", EntityType.BODY), qCreatedBy(id + "head", EntityType.BODY)]);
    opBoolean(context, id + "join", {"tools" : parts, "operationType" : BooleanOperationType.UNION});
    finish(context, parts, name, rgb);
    return parts;
}

annotation { "Feature Type Name" : "FunctorLimitSculpture",
             "Feature Type Description" : "A tilted ivory torus, charcoal lattice, pearl node, and three colored arrows above a prominent freestanding functor.systems sign." }
export const functorLimitSculpture = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Overall height" }
        isLength(definition.height, { (millimeter) : [150, 202, 300] } as LengthBoundSpec);
    }
    {
        var unit = definition.height / 202;
        var ivory = [242, 239, 226];
        var graphite = [28, 32, 39];
        var latticeColor = [16, 19, 24];
        var tilt = 32 * degree;
        var u = vector(1, 0, 0);
        var n = vector(0, -sin(tilt), cos(tilt));
        var v = cross(n, u);
        var c = vector(0, 0, 104) * unit;
        var node = vector(0, 0, 189.7) * unit;

        var base = roundedBody(context, id + "pedestal", 109, 72, 12,
                vector(0, 0, 0), vector(0, 0, 1), 17, unit);
        finish(context, base, "Graphite gallery pedestal", graphite);
        var cap = roundedBody(context, id + "cap", 106, 69, 11,
                vector(0, 0, 17), vector(0, 0, 1), 2, unit);
        finish(context, cap, "Ivory pedestal crown", ivory);

        // Actual analytic torus: major radius 43 mm, tube radius 14 mm.
        var body = torus(context, id + "torus", c, n, 43 * unit, 14 * unit);

        // Two full families of circular solid ribs, not a texture or decal.
        var ribs = [];
        for (var i = 0; i < 32; i += 1)
        {
            var theta = i * 360 / 32 * degree;
            var radial = cos(theta) * u + sin(theta) * v;
            var tangent = -sin(theta) * u + cos(theta) * v;
            ribs = append(ribs, torus(context, id + ("meridian" ~ i),
                        c + 43 * unit * radial, tangent, 14 * unit, 0.44 * unit));
        }
        for (var i = 0; i < 12; i += 1)
        {
            var phi = i * 30 * degree;
            ribs = append(ribs, torus(context, id + ("parallel" ~ i),
                        c + 14 * sin(phi) * unit * n, n,
                        (43 + 14 * cos(phi)) * unit, 0.44 * unit));
        }
        var grid = qUnion(ribs);
        opBoolean(context, id + "weave", {"tools" : grid, "operationType" : BooleanOperationType.UNION});
        finish(context, grid, "Charcoal wireframe - 32 meridians and 12 parallels", latticeColor);
        opBoolean(context, id + "inlay", {"tools" : grid, "targets" : body,
                    "operationType" : BooleanOperationType.SUBTRACTION, "keepTools" : true});

        // Broad tapered columns carry the torus while retaining an open gap beneath it.
        var supports = [];
        for (var i = 0; i < 2; i += 1)
        {
            var theta = (225 + i * 90) * degree;
            var contact = pointOnTorus(c, u, v, n, theta, 270 * degree, unit);
            var supportId = id + ("support" ~ i);
            fCone(context, supportId, {"bottomCenter" : vector(contact[0], -8 * unit, 18 * unit),
                        "topCenter" : contact + 6 * unit * n,
                        "bottomRadius" : 8 * unit, "topRadius" : 6 * unit});
            var support = qCreatedBy(supportId, EntityType.BODY);
            finish(context, support, "Tapered graphite support - 16 mm foot / 12 mm crown", graphite);
            supports = append(supports, support);
        }

        // Full 3D arrows meet three different regions of the torus surface.
        var blue = arrow(context, id + "blue", node,
                pointOnTorus(c, u, v, n, 225 * degree, 35 * degree, unit), unit,
                "Blue projection", [15, 98, 254]);
        var red = arrow(context, id + "red", node,
                pointOnTorus(c, u, v, n, 90 * degree, 140 * degree, unit), unit,
                "Red projection", [172, 47, 59]);
        var green = arrow(context, id + "green", node,
                pointOnTorus(c, u, v, n, 315 * degree, 35 * degree, unit), unit,
                "Green projection", [66, 190, 101]);
        var arrows = qUnion([blue, red, green]);

        opSphere(context, id + "node", {"center" : node, "radius" : 11.8 * unit});
        var ball = qCreatedBy(id + "node", EntityType.BODY);
        var halo = torus(context, id + "nodeRim", node, vector(0, -1, 0), 11.75 * unit, 0.55 * unit);
        finish(context, halo, "Graphite equator around the pearl node", latticeColor);

        // Remove overlaps while retaining separate colored parts for material assignment.
        var inserts = qUnion([arrows, qUnion(supports)]);
        opBoolean(context, id + "torusSeats", {"tools" : inserts, "targets" : body,
                    "operationType" : BooleanOperationType.SUBTRACTION, "keepTools" : true});
        opBoolean(context, id + "gridSeats", {"tools" : inserts, "targets" : grid,
                    "operationType" : BooleanOperationType.SUBTRACTION, "keepTools" : true});
        opBoolean(context, id + "nodeSeats", {"tools" : qUnion([arrows, halo]), "targets" : ball,
                    "operationType" : BooleanOperationType.SUBTRACTION, "keepTools" : true});
        opBoolean(context, id + "capSeats", {"tools" : qUnion(supports), "targets" : cap,
                    "operationType" : BooleanOperationType.SUBTRACTION, "keepTools" : true});
        finish(context, body, "Ivory torus with inlaid wireframe", ivory);
        finish(context, ball, "Pearl limit point", [250, 248, 240]);

        if (size(WORDMARK) > 0)
        {
            // A separate, upright yard sign on two posts, ahead of the sculpture.
            var frame = roundedBody(context, id + "signFrame", 102, 18, 3,
                    vector(0, -58, 44), vector(0, -1, 0), 5, unit);
            var face = roundedBody(context, id + "signFace", 100, 16, 2,
                    vector(0, -63, 44), vector(0, -1, 0), 0.8, unit);
            var postBodies = [frame];
            for (var i = 0; i < 2; i += 1)
            {
                var x = (i == 0 ? -82 : 82) * unit;
                var postId = id + ("signPost" ~ i);
                fCuboid(context, postId, {
                            "corner1" : vector(x - 4.5 * unit, -63 * unit, 18 * unit),
                            "corner2" : vector(x + 4.5 * unit, -58 * unit, 29 * unit)});
                postBodies = append(postBodies, qCreatedBy(postId, EntityType.BODY));
            }
            opBoolean(context, id + "signStructure", {
                        "tools" : qUnion(postBodies), "operationType" : BooleanOperationType.UNION});
            opBoolean(context, id + "signPostSeats", {"tools" : frame, "targets" : cap,
                        "operationType" : BooleanOperationType.SUBTRACTION, "keepTools" : true});
            finish(context, frame, "Freestanding graphite sign frame and two posts", graphite);
            finish(context, face, "Ivory yard sign face", ivory);
            if (size(evaluateQuery(context, frame)) != 1)
                throw regenError("Sign frame and posts must form one connected solid.");

            var letters = newSketchOnPlane(context, id + "wordmark", {
                        "sketchPlane" : plane(vector(0, -63.8, 0) * unit, vector(0, -1, 0), u)});
            for (var i = 0; i < size(WORDMARK); i += 1)
            {
                var points = [];
                for (var point in WORDMARK[i])
                    points = append(points, vector(point[0], point[1]) * unit);
                skPolyline(letters, "outline" ~ i, {"points" : points});
            }
            skSolve(letters);
            opExtrude(context, id + "lettering", {"entities" : qSketchRegion(id + "wordmark", true),
                        "direction" : vector(0, -1, 0), "endBound" : BoundingType.BLIND, "endDepth" : 2.8 * unit});
            finish(context, qCreatedBy(id + "lettering", EntityType.BODY), "Prominent sculpted Redaction wordmark", latticeColor);
            opDeleteBodies(context, id + "letterSketchClean", {"entities" : qCreatedBy(id + "wordmark", EntityType.BODY)});
        }

        if (size(evaluateQuery(context, body)) != 1)
            throw regenError("The torus must remain one connected solid.");
        if (size(evaluateQuery(context, ball)) != 1)
            throw regenError("The sphere must remain one connected solid.");
        for (var projection in [blue, red, green])
            if (size(evaluateQuery(context, projection)) != 1)
                throw regenError("Each arrow must remain one connected solid.");
        if (size(evaluateQuery(context, grid)) != 1)
            throw regenError("Wireframe must be a continuous connected lattice.");
        var solids = qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID);
        println("Sculpture complete: " ~ size(evaluateQuery(context, solids)) ~ " solid parts.");
        println("Solid volume: " ~ evVolume(context, {"entities" : solids}));
    }, { "height" : 202 * millimeter });
